import { useEffect, useRef } from "react";
import { useSelector, useDispatch } from "react-redux";
import {
  fetchProducts,
  selectProducts,
  resetProducts,
  loadFromCache,
} from "../../store/slices/productsSlice";
import { selectFilter, setFilters } from "../../store/slices/filterSlice";
import { useSearchParams } from "react-router-dom";

import ProductItem from "../product-item/ProductItem";
import Error from "../error/Error";
import Preloader from "../preloader/Preloader";

import "./products-list.css";

const ProductsList = () => {
  const dispatch = useDispatch();
  const { activeCategory, activeSortItem, searchValue, sortItems } =
    useSelector(selectFilter);

  const { items, loading, error, page, isMoreItems, cache } =
    useSelector(selectProducts);
  const [searchParams, setSearchParams] = useSearchParams();

  const activeSortValue = activeSortItem[1];
  const isMounted = useRef(false);
  const isSearchParams = useRef(false);
  const loadMoreRef = useRef();
  const cacheKey = `${activeCategory}_${activeSortValue}_${searchValue}`;
  console.log(activeCategory, activeSortItem, searchValue);

  useEffect(() => {
    const params = Object.fromEntries([...searchParams]);
    const sortItem = sortItems.find((item) =>
      item.includes(params.activeSortValue)
    );

    if (Object.keys(params).length) {
      dispatch(setFilters({ ...params, sortItem }));
      isSearchParams.current = true;
    }
  }, []);

  useEffect(() => {
    console.log(isMounted.current);
    if (isMounted.current) {
      setSearchParams({ activeSortValue, activeCategory, searchValue });
    }
    isMounted.current = true;
  }, [activeCategory, activeSortItem, searchValue]);

  useEffect(() => {
    window.scrollTo(0, 0);

    if (!isSearchParams.current) {
      dispatch(resetProducts());

      if (cache[cacheKey]) {
        dispatch(loadFromCache({ cacheKey }));
      } else {
        dispatch(
          fetchProducts({
            activeCategory,
            activeSortValue,
            searchValue,
            page: 1,
          })
        );
      }
    }
    isSearchParams.current = false;
  }, [activeCategory, activeSortItem, searchValue]);

  useEffect(() => {
    const observer = new IntersectionObserver((entries) => {
      if (entries[0].isIntersecting && isMoreItems) {
        fetchMoreProducts();
      }
    });

    if (observer && loadMoreRef.current) {
      observer.observe(loadMoreRef.current);
    }

    return () => observer.disconnect();
  }, [items]);

  const fetchMoreProducts = () => {
    dispatch(
      fetchProducts({ activeCategory, activeSortValue, searchValue, page })
    );
  };

  const products = items.map((product) => (
    <ProductItem key={product.id} {...product} />
  ));

  return (
    <>
      <h2 hidden>Products</h2>
      <div className="products-wrapper">
        {loading ? (
          <Preloader />
        ) : error ? (
          <Error message={error} />
        ) : items.length ? (
          products
        ) : (
          <p className="products-not-found">Products Not Found</p>
        )}
      </div>
      {isMoreItems && (
        <p ref={loadMoreRef} className="products-load-more">
          Loading more ...
        </p>
      )}
    </>
  );
};

export default ProductsList;
