import { useEffect, useState } from "react";

import "./page-up.css";

const PageUp = () => {
  const [visibility, setVisibility] = useState(false);

  useEffect(() => {
    window.addEventListener("scroll", () => {
      const scrollHeightPoint = document.documentElement.scrollHeight / 4;

      setVisibility(window.scrollY > scrollHeightPoint);

      // return wo to tam
    });
  }, []);

  return (
    <button
      onClick={() => window.scrollTo(0, 0)}
      title="Scroll up"
      className={`page-up ${visibility ? "visible" : ""}`}
    ></button>
  );
};

export default PageUp;
