import { useSwipeable } from "react-swipeable";

import { useState } from "react";
import { useDispatch } from "react-redux";
import { changeItemsCount } from "../../store/slices/cartSlice";

import "./product-item.css";

const ProductItem = ({ name, price, descr, images, colors, id }) => {
  const [checkedColorIndex, setCheckedColorIndex] = useState(0);
  const [activeSlide, setActiveSlide] = useState(0);
  const [isImgLoaded, setImgLoaded] = useState(false);
  const currentImages = images[colors[checkedColorIndex]];

  const dispatch = useDispatch();

  const onChangeColor = (i) => {
    setCheckedColorIndex(i);
    setActiveSlide(0);
    setImgLoaded(false);
  };

  const onChangeSlide = (newActiveSlide) => {
    if (newActiveSlide < 0) {
      newActiveSlide = 0;
    } else if (newActiveSlide >= currentImages.length) {
      newActiveSlide = currentImages.length - 1;
    }

    setActiveSlide(newActiveSlide);
  };
  const touchHandlers = useSwipeable({
    onSwipedLeft: () => onChangeSlide(activeSlide + 1),
    onSwipedRight: () => onChangeSlide(activeSlide - 1),
    preventScrollOnSwipe: true,
    trackTouch: true,
    swipeDuration: 1500,
  });
  const onAddToCart = () => {
    //
    const cartItem = {
      name,
      price,
      image: currentImages[0],
      id: `${id}-${colors[checkedColorIndex]}`,
      color: colors[checkedColorIndex],
      count: 1,
    };
    dispatch(changeItemsCount({ cartItem }));
  };

  return (
    <div className="product">
      <div>
        <div className="product-slider" {...touchHandlers}>
          {currentImages.map((imgUrl, i) => (
            <img
              src={imgUrl}
              alt={name}
              key={i}
              style={{ transform: `translateX(-${100 * activeSlide}%)` }}
              className={`product-slider-image ${isImgLoaded ? "visible" : ""}`}
              loading="lazy"
              onLoad={() => setImgLoaded(true)}
            />
          ))}
          {currentImages.length > 1 && (
            <div className="product-slider-nav-wrapper">
              <div className="product-slider-pagination">
                {currentImages.map((_, i) => (
                  <span
                    key={i}
                    className={activeSlide === i ? "active" : null}
                  ></span>
                ))}
              </div>
              <div className="product-slider-nav">
                <button onClick={() => onChangeSlide(activeSlide - 1)}>
                  ‹
                </button>
                <button onClick={() => onChangeSlide(activeSlide + 1)}>
                  ›
                </button>
              </div>
            </div>
          )}
        </div>
        {!isImgLoaded && <div className="product-img-placeholder"></div>}
        <div className="product-inner">
          <h3>{name}</h3>
          <span className="product-price">{price} UAH</span>
        </div>
        <p>{descr}</p>
      </div>

      <div>
        <ul className="product-colors">
          {colors.map((color, i) => (
            <li
              key={color}
              style={{ background: `var(--${color})` }}
              className={i === checkedColorIndex ? "checked" : null}
              onClick={() => onChangeColor(i)}
            ></li>
          ))}
        </ul>

        <button className="btn btn--add-cart" onClick={onAddToCart}>
          + Add to Cart
        </button>
      </div>
    </div>
  );
};

export default ProductItem;
