import { useSelector } from "react-redux";
import { selectCart } from "../../store/slices/cartSlice";
import "./add-product-alert.css";
import { useEffect, useState, useRef } from "react";

const AddProductAlert = () => {
  const [visible, setVisible] = useState("");
  const { totalCount } = useSelector(selectCart);
  const isMounted = useRef(false);

  useEffect(() => {
    if (isMounted.current && totalCount > 0) {
      setVisible("visible");
    }
    isMounted.current = true;
    const timeoutId = setTimeout(() => {
      setVisible("");
    }, 800);
    return () => clearTimeout(timeoutId);
  }, [totalCount]);

  return (
    <div className={`add-product-alert ${visible}`}>
      <p>&#x2713; Added to Cart </p>
    </div>
  );
};

export default AddProductAlert;
