import { useSelector, useDispatch } from "react-redux";
import {
  selectFilter,
  setActiveSortItem,
} from "../../store/slices/filterSlice";
import { useState, useEffect } from "react";
import "./sort.css";

const Sort = () => {
  const { sortItems, activeSortItem } = useSelector(selectFilter);
  const [isOpen, setOpen] = useState(false);
  const dispatch = useDispatch();

  const onCloseSort = (e) => {
    if (!e.target.classList.contains("sort-current")) {
      setOpen(false);
    }
  };

  useEffect(() => {
    window.addEventListener("click", onCloseSort);
    return () => window.removeEventListener("click", onCloseSort);
  }, []);

  return (
    <div className={`sort ${isOpen ? "open" : ""}`}>
      <p className="sort-current" onClick={() => setOpen((isOpen) => !isOpen)}>
        Sort: {activeSortItem[0]}
      </p>
      <ul className="sort-list">
        {sortItems.map((item) => (
          <li
            className={`sort-item ${
              item[0] === activeSortItem[0] ? "active" : ""
            }`}
            onClick={() => dispatch(setActiveSortItem({ item }))}
            key={item[0]}
          >
            {item[0]}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default Sort;
